// Compensating deletion only, against a signed receipt of actual newly added pairs.
#include "remove_support.hpp"
static const char* stage="arguments";
struct Removal{std::string pinyin,word,record,metadata;bool closure=false;};
static bool hex64(const std::string&s){return s.size()==64&&s.find_first_not_of("0123456789abcdef")==std::string::npos;}
static int compensate(const fs::path&root,const fs::path&job){checkedInputs(root,job);isolate(root,job);loadSecret(job);alarm(1800);stage="receipt";const auto file=job/"remove-permit.txt";checkedNode(file);if(fs::file_size(file)>512000)throw std::runtime_error("permit bound");std::ifstream f(file,std::ios::binary);std::string raw(std::istreambuf_iterator<char>(f),{});auto sigpos=raw.rfind("SIGNATURE\t");if(sigpos==std::string::npos||raw.size()!=sigpos+10+64+1||raw.back()!='\n')throw std::runtime_error("permit signature shape");auto body=raw.substr(0,sigpos),signature=raw.substr(sigpos+10,64);if(!hex64(signature)||tag(std::string("remove-permit-v1")+body)!=signature)throw std::runtime_error("permit signature rejected");std::istringstream input(body);std::string version,expectedHash,countLine,line;std::getline(input,version);std::getline(input,expectedHash);std::getline(input,countLine);if(version!="WETYPE_REMOVE_RECEIPT_V1"||!hex64(expectedHash)||countLine.empty()||countLine.size()>7||countLine.find_first_not_of("0123456789")!=std::string::npos)throw std::runtime_error("permit header rejected");size_t expectedCount=std::stoull(countLine);if(expectedCount>5000000)throw std::runtime_error("record count bound");std::vector<Removal>rows;std::set<std::string>targets;
 while(std::getline(input,line)){std::istringstream fields(line);Removal r;std::string extra;if(!std::getline(fields,r.pinyin,'\t')||!std::getline(fields,r.word,'\t')||!std::getline(fields,r.record,'\t')||!std::getline(fields,r.metadata,'\t')||std::getline(fields,extra,'\t')||!validPinyin(r.pinyin)||!validUtf8Word(r.word)||!hex64(r.record)||!hex64(r.metadata)||r.record!=recordKey(r.pinyin,r.word)||!targets.insert(r.record).second||rows.size()>=500)throw std::runtime_error("permit row rejected");rows.push_back(std::move(r));}if(rows.empty())throw std::runtime_error("no eligible newly-added pairs");
 stage="engine-preflight";RemoveEngine engine(root,job,2*rows.size());RecordMap before,after;{auto user=learningDict(engine.h);stage="records-before";before=exportRecords(engine.h,user.get());if(aggregate(before)!=expectedHash||recordCount(before)!=expectedCount)throw std::runtime_error("later learning conflict");using Pair=uint64_t(*)(void*,std::string_view,std::string_view);using Remove=std::function<void()>(*)(void*,std::string_view,std::string_view);
 // Check the entire batch before issuing the first native mutation.
 for(auto&r:rows){auto it=before.find(r.record);uint64_t pair=entry<Pair>(engine.slide,kLookUpPair)(user.get(),r.pinyin,r.word);if(it==before.end()||it->second!=std::vector<std::string>{r.metadata}||!((pair>>32)&1)||(uint32_t)pair!=1)throw std::runtime_error("receipt target changed");}
 stage="native-remove";for(auto&r:rows){auto wait=entry<Remove>(engine.slide,0x1017aff10)(user.get(),r.pinyin,r.word);r.closure=(bool)wait;if(wait)wait();uint64_t pair=entry<Pair>(engine.slide,kLookUpPair)(user.get(),r.pinyin,r.word);if((pair>>32)&1)throw std::runtime_error("Remove pair still present");}
 stage="records-after";after=exportRecords(engine.h,user.get());RecordMap expected=before;for(auto&r:rows)expected.erase(r.record);if(after!=expected||recordCount(after)+rows.size()!=recordCount(before))throw std::runtime_error("exact Remove record audit failed");}
 stage="queue-after";engine.close();auto queue=readQueue(engine.h,job);size_t delta=queue.counter-engine.before.counter;if(queue.counter<engine.before.counter||delta<rows.size()||delta>2*rows.size()||queue.actions.size()!=engine.before.actions.size()+delta||queue.watermark!=engine.before.watermark)throw std::runtime_error("Remove queue delta rejected");for(auto&a:engine.before.actions){auto it=std::find_if(queue.actions.begin(),queue.actions.end(),[&](const auto&b){return a.seq==b.seq;});if(it==queue.actions.end()||it->payload_tag!=a.payload_tag)throw std::runtime_error("previous action changed");}for(uint64_t seq=engine.before.counter+1;seq<=queue.counter;++seq){auto it=std::find_if(queue.actions.begin(),queue.actions.end(),[&](const auto&a){return a.seq==seq;});if(it==queue.actions.end()||it->kind!=128||(it->type!=1&&it->type!=2)||std::none_of(rows.begin(),rows.end(),[&](const auto&r){return r.pinyin==it->a;}))throw std::runtime_error("new Remove action rejected");}
 stage="action-payload";std::set<std::string>dropItems;for(auto&a:queue.actions)if(a.seq>engine.before.counter){if(a.type==2){if(a.b.size()<51||a.b[0]!=0||le16(a.b,1)+51!=a.b.size())throw std::runtime_error("drop item payload bounds");std::string word=a.b.substr(51),rk=recordKey(a.a,word);auto r=std::find_if(rows.begin(),rows.end(),[&](const auto&r){return r.record==rk;});if(r==rows.end()||tag(std::string("meta")+a.b.substr(3,48))!=r->metadata||!dropItems.insert(rk).second)throw std::runtime_error("drop item target rejected");}else if(a.type==1&&!a.b.empty())throw std::runtime_error("drop syllable payload rejected");}if(dropItems!=targets)throw std::runtime_error("missing exact drop-item actions");
 std::ostringstream out;out<<"{\"schema\":1,\"mode\":\"compensate\",\"pid\":"<<getpid()<<",\"removed\":"<<rows.size()<<",\"other_metadata_unchanged\":true,\"before_count\":"<<recordCount(before)<<",\"after_count\":"<<recordCount(after)<<",\"before_hash\":"<<quote(aggregate(before))<<",\"after_hash\":"<<quote(aggregate(after))<<",\"queue_before\":"<<queueJson(engine.before)<<",\"queue_after\":"<<queueJson(queue)<<",\"rows\":[";for(size_t i=0;i<rows.size();++i){auto&r=rows[i];if(i)out<<',';out<<"{\"record_tag\":"<<quote(r.record)<<",\"pinyin\":"<<quote(r.pinyin)<<",\"word\":"<<quote(r.word)<<",\"completion_closure_present\":"<<(r.closure?"true":"false")<<",\"completion_wait_invoked\":"<<(r.closure?"true":"false")<<",\"present_after\":false}";}out<<"]}";printf("WETYPE_REMOVE_RESULT=%s\n",out.str().c_str());return 0;}
int main(int argc,char**argv){try{if(argc!=4||std::string(argv[3])!="compensate")throw std::runtime_error("mode rejected");return compensate(checkedPath(argv[1]),checkedPath(argv[2]));}catch(...){fprintf(stderr,"compensation rejected stage=%s\n",stage);fflush(nullptr);_exit(43);}}
